-- Name: units_id_seq; Type: SEQUENCE OWNED BY; Schema: public; Owner: -
--

ALTER SEQUENCE public.units_id_seq OWNED BY public.units.id;


--
-- Name: weapon_types; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.weapon_types (
    id smallint NOT NULL,
    code character varying(32) NOT NULL,
    name_ua character varying(64) NOT NULL,
    category character varying(24) NOT NULL,
    sidc character varying(20) NOT NULL,
    color_hex character(7) NOT NULL,
    map_label character varying(8) NOT NULL,
    CONSTRAINT weapon_types_category_check CHECK (((category)::text = ANY ((ARRAY['uav'::character varying, 'cruise_missile'::character varying, 'ballistic_missile'::character varying, 'guided_bomb'::character varying])::text[])))
);


--
-- Name: v_air_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_air_daily AS
 SELECT ((s.occurred_at AT TIME ZONE 'Europe/Kyiv'::text))::date AS day,
    w.code AS weapon,
    w.category,
    count(*) AS events,
    sum(s.launched) AS launched,
    sum(s.intercepted) AS intercepted,
    sum(s.suppressed) AS suppressed,
    sum(s.hits) AS hits
   FROM (public.strike_events s
     JOIN public.weapon_types w ON ((w.id = s.weapon_type_id)))
  GROUP BY (((s.occurred_at AT TIME ZONE 'Europe/Kyiv'::text))::date), w.code, w.category;


--
-- Name: v_air_oblast; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_air_oblast AS
 SELECT o.iso_code,
    o.name_ua,
    count(s.id) AS events,
    COALESCE(sum(s.launched), (0)::bigint) AS launched,
    COALESCE(sum(s.intercepted), (0)::bigint) AS intercepted,
    COALESCE(sum(s.hits), (0)::bigint) AS hits
   FROM (public.oblasts o
     LEFT JOIN public.strike_events s ON ((s.oblast_id = o.id)))
  GROUP BY o.iso_code, o.name_ua;


--
-- Name: v_alert_summary; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_alert_summary AS
 SELECT o.iso_code,
    o.name_ua,
    a.alert_type,
    count(*) AS alerts,
    round(((sum(COALESCE(a.duration_min, 0)))::numeric / 60.0), 1) AS hours
   FROM (public.air_alerts a
     JOIN public.oblasts o ON ((o.id = a.oblast_id)))
  GROUP BY o.iso_code, o.name_ua, a.alert_type;


--
-- Name: v_art_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_art_daily AS
 SELECT ((occurred_at AT TIME ZONE 'Europe/Kyiv'::text))::date AS day,
    direction,
    system_type,
    count(*) AS shellings,
    sum(rounds) AS rounds
   FROM public.artillery_fire
  GROUP BY (((occurred_at AT TIME ZONE 'Europe/Kyiv'::text))::date), direction, system_type;


--
-- Name: v_art_hour_weekday; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_art_hour_weekday AS
 SELECT (EXTRACT(isodow FROM (occurred_at AT TIME ZONE 'Europe/Kyiv'::text)))::integer AS weekday,
    (EXTRACT(hour FROM (occurred_at AT TIME ZONE 'Europe/Kyiv'::text)))::integer AS hour,
    count(*) AS shellings,
    sum(rounds) AS rounds
   FROM public.artillery_fire
  WHERE ((direction)::text = 'incoming'::text)
  GROUP BY ((EXTRACT(isodow FROM (occurred_at AT TIME ZONE 'Europe/Kyiv'::text)))::integer), ((EXTRACT(hour FROM (occurred_at AT TIME ZONE 'Europe/Kyiv'::text)))::integer);


--
-- Name: v_as_of; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_as_of AS
 SELECT GREATEST(( SELECT (dataset_meta.value)::timestamp with time zone AS value
           FROM public.dataset_meta
          WHERE ((dataset_meta.key)::text = 'data_as_of'::text)), COALESCE(( SELECT max(strike_events.occurred_at) AS max
           FROM public.strike_events
          WHERE ((strike_events.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT max(artillery_fire.occurred_at) AS max
           FROM public.artillery_fire
          WHERE ((artillery_fire.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT max(air_alerts.started_at) AS max
           FROM public.air_alerts
          WHERE ((air_alerts.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT (max(personnel_losses.report_date))::timestamp with time zone AS max
           FROM public.personnel_losses
          WHERE ((personnel_losses.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT max(COALESCE(counter_battery.responded_at, counter_battery.detected_at)) AS max
           FROM public.counter_battery
          WHERE ((counter_battery.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT (max(ammo_supply.report_date))::timestamp with time zone AS max
           FROM public.ammo_supply
          WHERE ((ammo_supply.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT (max(artillery_equipment.report_date))::timestamp with time zone AS max
           FROM public.artillery_equipment
          WHERE ((artillery_equipment.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT (max(unit_strength.report_date))::timestamp with time zone AS max
           FROM public.unit_strength
          WHERE ((unit_strength.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone), COALESCE(( SELECT max(GREATEST(incoming_documents.received_at, COALESCE(incoming_documents.completed_at, incoming_documents.received_at))) AS max
           FROM public.incoming_documents
          WHERE ((incoming_documents.origin)::text <> 'synthetic'::text)), '-infinity'::timestamp with time zone)) AS as_of;


--
-- Name: v_docs_hourly; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_docs_hourly AS
 SELECT (EXTRACT(hour FROM (received_at AT TIME ZONE 'Europe/Kyiv'::text)))::integer AS hour,
    urgency,
    count(*) AS docs
   FROM public.incoming_documents
  GROUP BY ((EXTRACT(hour FROM (received_at AT TIME ZONE 'Europe/Kyiv'::text)))::integer), urgency;


--
-- Name: v_docs_sla; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_docs_sla AS
 SELECT d.urgency,
    n.name_ua,
    n.norm_min,
    n.sort_order,
    count(*) AS docs,
    percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY ((d.processing_min)::double precision)) AS median_min,
    percentile_cont((0.9)::double precision) WITHIN GROUP (ORDER BY ((d.processing_min)::double precision)) AS p90_min,
    round((100.0 * avg(
        CASE
            WHEN (d.due_at < COALESCE(d.completed_at, now())) THEN 1
            ELSE 0
        END)), 2) AS overdue_pct
   FROM (public.incoming_documents d
     JOIN public.doc_sla_norms n ON (((n.urgency)::text = (d.urgency)::text)))
  GROUP BY d.urgency, n.name_ua, n.norm_min, n.sort_order;


--
-- Name: v_losses_by_cause; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_losses_by_cause AS
 SELECT cause,
    sum(killed) AS killed,
    sum(wounded) AS wounded,
    sum(missing) AS missing
   FROM public.personnel_losses
  GROUP BY cause;


--
-- Name: v_losses_by_unit; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_losses_by_unit AS
 SELECT u.short_name,
    u.echelon,
    p.report_date AS day,
    sum(p.killed) AS killed,
    sum(p.wounded) AS wounded,
    sum(p.missing) AS missing
   FROM (public.personnel_losses p
     JOIN public.units u ON ((u.id = p.unit_id)))
  GROUP BY u.short_name, u.echelon, p.report_date;


--
-- Name: v_losses_daily; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_losses_daily AS
 SELECT report_date AS day,
    sum(killed) AS killed,
    sum(wounded) AS wounded,
    sum(missing) AS missing,
    sum(returned_to_duty) AS returned_to_duty
   FROM public.personnel_losses
  GROUP BY report_date;


